// Copyright 2026 ReC Sandbox. Distributed under the terms in LICENSE.md at the repository root.// The single translation unit that instantiates tinyexr's ~10k-line implementation. Keeping it// here rather than inside ExrImage.cpp means the library body is compiled once, under this// target's relaxed warning regime, and never lands in the renderer's PCH.//// TINYEXR_USE_MINIZ 0 selects the already-linked zlib over tinyexr's bundled miniz: a second// deflate in the same DLL would be 30 KB of duplicate code and a second CVE surface for no gain// (research/s6-exr-writer.md section 8).#define TINYEXR_USE_MINIZ 0#define TINYEXR_USE_STB_ZLIB 0#define TINYEXR_USE_THREAD 0// tinyexr's issue #46: with the bundled miniz switched off the library expects a zlib-compatible// API to already be visible, and deliberately does not include one itself.#include <zlib.h>#define TINYEXR_IMPLEMENTATION#include "tinyexr.h"